abel", "type": "text", "label": "Word read for a check mark", "help": "Read by screen readers in place of the check mark, for instance: Included.", "max": 40}, {"name": "not_included_label", "type": "text", "label": "Word read for a dash", "help": "Read by screen readers in place of the dash, for instance: Not included.", "max": 40}]","sample":"{"title": "Comparez nos trois offres", "intro": "<p>Les trois offres comprennent l’accès à votre espace client. Elles diffèrent par leur durée et par le support.</p>", "feature_heading": "Ce qui est compris", "plans": [{"name": "Essentiel", "note": "Pour démarrer", "highlighted": false, "button_label": "Choisir l’offre Essentiel", "button_url": "/offres/essentiel"}, {"name": "Confort", "note": "Le plus choisi", "highlighted": true, "button_label": "Choisir l’offre Confort", "button_url": "/offres/confort"}, {"name": "Premium", "note": "Pour les professionnels", "highlighted": false, "button_label": "Choisir l’offre Premium", "button_url": "/offres/premium"}], "rows": [{"feature": "Prix", "value_1": "19 € par mois", "check_1": false, "value_2": "39 € par mois", "check_2": false, "value_3": "79 € par mois", "check_3": false}, {"feature": "Durée d’engagement", "value_1": "Sans engagement", "check_1": false, "value_2": "12 mois", "check_2": false, "value_3": "24 mois", "check_3": false}, {"feature": "Support par e-mail", "value_1": "", "check_1": true, "value_2": "", "check_2": true, "value_3": "", "check_3": true}, {"feature": "Délai de réponse du support", "value_1": "48 heures", "check_1": false, "value_2": "24 heures", "check_2": false, "value_3": "4 heures", "check_3": false}, {"feature": "Support par téléphone", "value_1": "", "check_1": false, "value_2": "", "check_2": true, "value_3": "7 jours sur 7", "check_3": true}, {"feature": "Conseiller dédié", "value_1": "", "check_1": false, "value_2": "", "check_2": false, "value_3": "", "check_3": true}], "included_label": "Inclus", "not_included_label": "Non inclus"}","template":"<section class="compare">{% if props.title is not empty %}<h2 class="compare__title">{{ props.title }}</h2>{% endif %}{% if props.intro is not empty %}<div class="compare__intro">{{ props.intro }}</div>{% endif %}{% if props.plans is not empty %}<div class="compare__scroller" tabindex="0" role="region"{% if props.title is not empty %} aria-label="{{ props.title }}"{% endif %}><table class="compare__table"><thead><tr>{% if props.feature_heading is not empty %}<th scope="col" class="compare__corner">{{ props.feature_heading }}</th>{% else %}<td class="compare__corner"></td>{% endif %}{% for plan in props.plans|slice(0, 3) %}<th scope="col" class="compare__plan{% if plan.highlighted %} compare__plan--highlight{% endif %}"><span class="compare__plan-name">{{ plan.name }}</span>{% if plan.note is not empty %}<span class="compare__plan-note">{{ plan.note }}</span>{% endif %}</th>{% endfor %}</tr></thead><tbody>{% for row in props.rows %}<tr class="compare__row"><th scope="row" class="compare__feature">{{ row.feature }}</th>{% for plan in props.plans|slice(0, 3) %}{% set value = '' %}{% set check = false %}{% if loop.index == 1 %}{% set value = row.value_1 %}{% set check = row.check_1 %}{% elseif loop.index == 2 %}{% set value = row.value_2 %}{% set check = row.check_2 %}{% else %}{% set value = row.value_3 %}{% set check = row.check_3 %}{% endif %}<td class="compare__cell{% if plan.highlighted %} compare__cell--highlight{% endif %}">{% if check %}<span class="compare__check" aria-hidden="true"></span>{% if props.included_label is not empty %}<span class="compare__sr">{{ props.included_label }}</span>{% endif %}{% endif %}{% if value is not empty %}<span class="compare__value">{{ value }}</span>{% elseif not check %}<span class="compare__none" aria-hidden="true"></span>{% if props.not_included_label is not empty %}<span class="compare__sr">{{ props.not_included_label }}</span>{% endif %}{% endif %}</td>{% endfor %}</tr>{% endfor %}</tbody><tfoot><tr><td class="compare__corner"></td>{% for plan in props.plans|slice(0, 3) %}<td class="compare__cell compare__cell--action{% if plan.highlighted %} compare__cell--highlight{% endif %}">{% if plan.button_label is not empty and plan.button_url is not empty %}<a class="compare__button{% if plan.highlighted %} compare__button--highlight{% endif %}" href="{{ plan.button_url }}">{{ plan.button_label }}</a>{% endif %}</td>{% endfor %}</tr></tfoot></table></div>{% endif %}</section>","css":".compare__title { margin-bottom: 0.75rem; }
.compare__intro { color: var(--cms-color-text-muted); margin-bottom: 1.5rem; }
