.compare__table th, .compare__table td { padding: 0.75rem 0.875rem; border-bottom: 1px solid var(--cms-color-border); vertical-align: middle; }
.compare__table tfoot td { border-bottom: 0; }
.compare__corner { text-align: left; font-weight: 600; color: var(--cms-color-text-muted); }
.compare__plan { text-align: center; vertical-align: bottom; }
