.compare__plan--highlight .compare__plan-note { color: var(--cms-color-on-accent); }
.compare__feature { text-align: left; font-weight: 600; }
.compare__cell { text-align: center; }
.compare__cell--highlight { background: var(--cms-color-accent-surface); }
.compare__value { display: inline-block; }
.compare__check { display: inline-block; width: 0.45rem; height: 0.9rem; margin: 0 0.4rem 0.2rem; border: solid var(--cms-color-accent-strong); border-width: 0 3px 3px 0; transform: rotate(45deg); vertical-align: middle; }
.compare__none { display: inline-block; width: 0.9rem; height: 2px; background: var(--cms-color-text-faint); vertical-align: middle; }
.compare__sr { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.compare__button { display: inline-block; padding: 0.5rem 1rem; border: 2px solid var(--cms-color-accent); border-radius: 0.375rem; color: var(--cms-color-accent-strong); font-weight: 600; text-decoration: none; transition: background-color 0.2s ease, color 0.2s ease; }
.compare__button:hover, .compare__button:focus-visible { background: var(--cms-color-accent); color: var(--cms-color-on-accent); }
.compare__button--highlight { background: var(--cms-color-accent); color: var(--cms-color-on-accent); }
.compare__button--highlight:hover, .compare__button--highlight:focus-visible { background: var(--cms-color-accent-strong); border-color: var(--cms-color-accent-strong); color: var(--cms-color-on-accent); }
